package com.aarontap.rpg;

import android.app.Activity;
import android.content.Context;
import android.content.SharedPreferences;
import android.graphics.*;
import android.os.Bundle;
import android.os.VibrationEffect;
import android.os.Vibrator;
import android.view.*;
import java.util.*;

public class MainActivity extends Activity {
  @Override public void onCreate(Bundle b){super.onCreate(b);setTitle("Monster Tamer: New Journey");setContentView(new GameView(this));}
  static class GameView extends View {
    Paint p=new Paint(Paint.ANTI_ALIAS_FLAG), text=new Paint(Paint.ANTI_ALIAS_FLAG); Random r=new Random(); SharedPreferences sp; Vibrator vib;
    int screen=0, enemy, enemyHp, playerHp=100, playerMax=100, xp=0, level=1, gold=50, wins=0, tames=0, selected=0;
    boolean defending=false; ArrayList<Integer> party=new ArrayList<>(); boolean[] caught=new boolean[120]; int[] monsterLevel=new int[120];
    String[] names={"Azure Slime","Moss Slime","Ember Slime","Frost Slime","Spark Slime","Moon Slime","Iron Slime","Royal Slime","Bubble Beast","Mud Blob","Greenhorn Goblin","Redcap Goblin","Stone Goblin","Cave Orc","Hill Orc","Brutish Orc","Forest Troll","Stone Troll","Bog Troll","Cyclops","Wolf Pup","Dire Wolf","Moon Wolf","Frost Wolf","Thunder Hound","Wildcat","Sabertooth","Golden Lion","Horned Boar","Iron Boar","Tiny Drake","Red Drake","Blue Drake","Green Drake","Winged Dragon","Stone Dragon","Sea Dragon","Thunder Dragon","Ancient Dragon","Star Dragon","Baby Bat","Night Bat","Vampire Bat","Winged Imp","Red Imp","Blue Imp","Dark Imp","Demon Knight","Ash Demon","Void Demon","Forest Sprite","Leaf Fairy","Bloom Fairy","Mushroomkin","Mandrake","Treant","Ancient Treant","Dryad","Thorn Beast","Bramble King","Sand Scorpion","Rock Crab","Shellback","Cactus Crawler","Dune Beast","Desert Jackal","Sand Worm","Mirage Moth","Sun Beetle","Golden Scarab","River Fish","Piranha","Jellyfish","Sea Serpent","Coral Crab","Tide Turtle","Sharkling","Great Shark","Kraken Spawn","Deep Kraken","Snow Hare","Ice Wolf","Frost Ape","Yeti","Snow Golem","Ice Elemental","Aurora Bird","Glacier Bear","White Stag","Frost Queen","Tiny Golem","Clay Golem","Iron Golem","Obsidian Golem","Clockwork","Copper Knight","Silver Knight","Gold Knight","Crystal Giant","Titan","Ghost","Wisp","Haunted Doll","Bone Dog","Skeleton","Skeleton Mage","Wraith","Grave Knight","Phantom Dragon","Death Herald","Rainbow Bird","Phoenix Chick","Phoenix","Unicorn","Pegasus","Griffin","Chimera","Basilisk","Manticore","World Serpent"};
    String[] zones={"Greenvale Fields","Whispering Woods","Sunscar Desert","Moonlit Coast","Frostpeak Pass","Ancient Ruins"};
    GameView(Context c){super(c);sp=c.getSharedPreferences("monster_tamer",0);vib=(Vibrator)c.getSystemService(Context.VIBRATOR_SERVICE);load();text.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));setFocusable(true);}
    void load(){level=sp.getInt("level",1);xp=sp.getInt("xp",0);gold=sp.getInt("gold",50);wins=sp.getInt("wins",0);tames=sp.getInt("tames",0);playerMax=80+level*20;playerHp=sp.getInt("hp",playerMax);for(int i=0;i<120;i++){caught[i]=sp.getBoolean("c"+i,false);monsterLevel[i]=sp.getInt("l"+i,1);if(caught[i]&&!party.contains(i)&&party.size()<4)party.add(i);}}
    void save(){SharedPreferences.Editor e=sp.edit().putInt("level",level).putInt("xp",xp).putInt("gold",gold).putInt("wins",wins).putInt("tames",tames).putInt("hp",playerHp);for(int i=0;i<120;i++)if(caught[i])e.putBoolean("c"+i,true).putInt("l"+i,monsterLevel[i]);e.apply();}
    float d(){return getResources().getDisplayMetrics().density;} void rect(Canvas c,float a,float b,float x,float y,int col){p.setColor(col);p.setStyle(Paint.Style.FILL);c.drawRect(a,b,x,y,p);} void round(Canvas c,float a,float b,float x,float y,int col){p.setColor(col);p.setStyle(Paint.Style.FILL);c.drawRoundRect(a,b,x,y,18,18,p);} void label(Canvas c,String s,float x,float y,float size,int col){text.setTextSize(size);text.setColor(col);text.setTextAlign(Paint.Align.CENTER);c.drawText(s,x,y,text);}
    @Override protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();rect(c,0,0,w,h,Color.rgb(12,19,31));if(screen==0)title(c,w,h);else if(screen==1)world(c,w,h);else if(screen==2)battle(c,w,h);else if(screen==3)collection(c,w,h);else camp(c,w,h);}
    void title(Canvas c,float w,float h){for(int y=0;y<12;y++)for(int x=0;x<7;x++)rect(c,x*w/7,y*h/12,(x+1)*w/7,(y+1)*h/12,((x+y)%2==0)?0xFF2E6B45:0xFF3A774B);p.setColor(0xFF86C7E8);c.drawCircle(w*.75f,h*.18f,42*d(),p);p.setColor(0xFFFFD45A);c.drawCircle(w*.75f,h*.18f,30*d(),p);p.setColor(0xFF5A3A27);c.drawRect(w*.38f,h*.18f,w*.62f,h*.44f,p);p.setColor(0xFF7E5136);c.drawCircle(w*.50f,h*.18f,55*d(),p);label(c,"MONSTER TAMER",w/2,90*d(),34*d(),Color.WHITE);label(c,"A NEW JOURNEY",w/2,126*d(),18*d(),0xFFFFD45A);round(c,w*.16f,h*.57f,w*.84f,h*.64f,0xDD101A2B);label(c,"BEGIN ADVENTURE",w/2,h*.615f,19*d(),Color.WHITE);round(c,w*.16f,h*.66f,w*.84f,h*.73f,0xDD101A2B);label(c,"CONTINUE",w/2,h*.705f,19*d(),Color.WHITE);label(c,"Explore • Battle • Tame • Grow",w/2,h*.82f,14*d(),Color.WHITE);}
    void header(Canvas c,float w,String title){rect(c,0,0,w,68*d(),0xFF172A43);label(c,title,w/2,43*d(),22*d(),Color.WHITE);}
    void nav(Canvas c,float w,float h){rect(c,0,h-66*d(),w,h,0xFF172A43);String[] a={"WORLD","BATTLE","MONSTERS","CAMP"};for(int i=0;i<4;i++)label(c,a[i],w*(.125f+i*.25f),h-27*d(),12*d(),screen==i+1?0xFFFFD45A:Color.WHITE);}
    void world(Canvas c,float w,float h){header(c,w,"GREENVALE REALM");float top=82*d();for(int y=0;y<5;y++)for(int x=0;x<4;x++){float xx=x*w/4,yy=top+y*72*d();rect(c,xx,yy,xx+w/4,yy+72*d(),(x+y)%2==0?0xFF3C7848:0xFF467F4F);for(int k=0;k<4;k++){p.setColor(0xFF285A35);c.drawCircle(xx+20*d()+k*32*d(),yy+20*d()+((x*7+k*11)%35),12*d(),p);}}round(c,w*.08f,h*.20f,w*.92f,h*.42f,0xDD102033);label(c,"THE ROAD AHEAD",w/2,h*.245f,18*d(),0xFFFFD45A);label(c,zones[(wins/3)%zones.length],w/2,h*.30f,22*d(),Color.WHITE);label(c,"Choose a route, then face a wild monster.",w/2,h*.35f,13*d(),0xFFD6E4F5);round(c,w*.12f,h*.46f,w*.88f,h*.55f,0xFF234B6A);label(c,"GO HUNTING",w/2,h*.515f,19*d(),Color.WHITE);round(c,w*.12f,h*.58f,w*.88f,h*.67f,0xFF5A3C29);label(c,"REST AT INN  •  20 G",w/2,h*.635f,16*d(),Color.WHITE);label(c,"Level "+level+"    XP "+xp+" / "+(level*50)+"    Gold "+gold,w/2,h*.73f,15*d(),0xFFFFD45A);nav(c,w,h);}
    void battle(Canvas c,float w,float h){header(c,w,"WILD ENCOUNTER");String nm=names[enemy];round(c,w*.08f,86*d(),w*.92f,300*d(),0xFF1B2B3D);drawMonster(c,w/2,190*d(),enemy,1.0f);label(c,nm,w/2,250*d(),22*d(),Color.WHITE);label(c,"HP "+enemyHp+" / "+(40+enemy%30+level*4),w/2,278*d(),14*d(),0xFFFFD45A);round(c,w*.08f,320*d(),w*.92f,370*d(),0xFF111B2A);label(c,"Hero Lv."+level+"   HP "+playerHp+"/"+playerMax,w/2,352*d(),14*d(),Color.WHITE);String[] acts={"ATTACK","TAME","GUARD","RUN"};for(int i=0;i<4;i++){float yy=395*d()+i*58*d();round(c,w*.12f,yy,w*.88f,yy+45*d(),i==1?0xFF6C4C2C:0xFF24496A);label(c,acts[i],w/2,yy+30*d(),17*d(),Color.WHITE);}label(c,"Victories "+wins+"   Tamed "+tames+"/120",w/2,h-86*d(),13*d(),0xFFD6E4F5);}
    void collection(Canvas c,float w,float h){header(c,w,"MONSTER BOOK  "+tames+" / 120");int pageStart=(selected/18)*18;for(int i=0;i<18;i++){int id=i+pageStart;if(id>=120)break;float xx=(i%3)*w/3+w/6,yy=94*d()+(i/3)*83*d();drawMonster(c,xx,yy,id,caught[id]?0.62f:0.48f);label(c,caught[id]?names[id]:"???",xx,yy+31*d(),11*d(),caught[id]?Color.WHITE:0xFF78879A);}label(c,"Tap a monster • page "+(pageStart/18+1)+"/7",w/2,h-78*d(),13*d(),0xFFFFD45A);nav(c,w,h);}
    void camp(Canvas c,float w,float h){header(c,w,"TAMER'S CAMP");round(c,w*.08f,90*d(),w*.92f,180*d(),0xFF263A4B);label(c,"Your Active Party",w/2,118*d(),19*d(),0xFFFFD45A);for(int i=0;i<4;i++){if(i<party.size()){int id=party.get(i);drawMonster(c,w*(.125f+i*.25f),151*d(),id,.42f);label(c,names[id],w*(.125f+i*.25f),177*d(),9*d(),Color.WHITE);}else label(c,"EMPTY",w*(.125f+i*.25f),160*d(),11*d(),0xFF8FA3B8);}round(c,w*.10f,210*d(),w*.90f,280*d(),0xFF234B6A);label(c,"ADVENTURE",w/2,253*d(),18*d(),Color.WHITE);round(c,w*.10f,300*d(),w*.90f,370*d(),0xFF4D382A);label(c,"HEAL PARTY  •  10 G",w/2,343*d(),16*d(),Color.WHITE);label(c,"Tamed monsters gain levels with victories.",w/2,415*d(),13*d(),0xFFD6E4F5);label(c,"Build a team of four from 120 species.",w/2,442*d(),13*d(),0xFFD6E4F5);nav(c,w,h);}
    void drawMonster(Canvas c,float x,float y,int id,float s){int a=0xFF000000|(((id*47+70)&255)<<16)|(((id*83+110)&255)<<8)|((id*131+150)&255);p.setColor(a);float q=28*d()*s;c.drawOval(new RectF(x-q,y-q*.7f,x+q,y+q*.8f),p);p.setColor(Color.WHITE);c.drawCircle(x-q*.35f,y-q*.15f,5*d()*s,p);c.drawCircle(x+q*.35f,y-q*.15f,5*d()*s,p);p.setColor(0xFF1B1B1B);c.drawCircle(x-q*.35f,y-q*.15f,2*d()*s,p);c.drawCircle(x+q*.35f,y-q*.15f,2*d()*s,p);p.setColor(0xFFFFD45A);c.drawCircle(x,y+q*.35f,3*d()*s,p);if(id%5==0){p.setColor(Color.WHITE);c.drawRect(x-q*1.1f,y-q*.4f,x-q*.7f,y+q*.1f,p);c.drawRect(x+q*.7f,y-q*.4f,x+q*1.1f,y+q*.1f,p);}}
    void encounter(){enemy=r.nextInt(120);enemyHp=40+enemy%30+level*4;screen=2;invalidate();}
    void action(int a){if(a==0){int dmg=12+level*4+r.nextInt(12);enemyHp-=dmg;xp+=8;if(enemyHp<=0){win();return;}enemyTurn();}else if(a==1){int chance=25+(enemyHp<((40+enemy%30+level*4)/3)?45:0)+(level>enemy/10?10:0);if(r.nextInt(100)<chance){tame();Toast("Tamed "+names[enemy]+"!");}else{Toast("It resisted!");enemyTurn();}}else if(a==2){defending=true;enemyTurn();}else if(r.nextInt(100)<55){Toast("Escaped!");screen=1;}else{Toast("Couldn't escape!");enemyTurn();}invalidate();}
    void enemyTurn(){int dmg=4+r.nextInt(9)+enemy%6;if(defending)dmg/=2;playerHp=Math.max(0,playerHp-dmg);defending=false;if(playerHp==0){gold=Math.max(0,gold-10);playerHp=playerMax;Toast("You were rescued at the inn.");screen=1;}}
    void win(){wins++;gold+=12+enemy%20;xp+=25+enemy%10;for(int id:party)monsterLevel[id]++;if(xp>=level*50){xp-=level*50;level++;playerMax=80+level*20;playerHp=playerMax;Toast("Level up! Lv."+level);}screen=1;save();}
    void tame(){if(!caught[enemy]){caught[enemy]=true;tames++;monsterLevel[enemy]=Math.max(1,level);if(party.size()<4)party.add(enemy);}win();}
    void Toast(String s){android.widget.Toast.makeText(getContext(),s,android.widget.Toast.LENGTH_SHORT).show();if(vib!=null&&android.os.Build.VERSION.SDK_INT>=26)try{vib.vibrate(VibrationEffect.createOneShot(35,VibrationEffect.DEFAULT_AMPLITUDE));}catch(Exception ignored){}}
    @Override public boolean onTouchEvent(MotionEvent e){if(e.getAction()!=MotionEvent.ACTION_UP)return true;float x=e.getX(),y=e.getY(),w=getWidth(),h=getHeight();if(screen==0){if(y>h*.52f&&y<h*.76f){screen=1;save();invalidate();}return true;}if(y>h-75*d()){int n=(int)(x/(w/4));screen=n+1;invalidate();return true;}if(screen==1){if(y>h*.43f&&y<h*.58f){encounter();return true;}if(y>h*.58f&&y<h*.69f){gold=Math.max(0,gold-20);playerHp=playerMax;save();Toast("Rested!");invalidate();return true;}}if(screen==2){for(int i=0;i<4;i++){float yy=395*d()+i*58*d();if(y>=yy&&y<=yy+47*d()){action(i);return true;}}}if(screen==3&&y>80*d()){int row=(int)((y-88*d())/(83*d()));int col=(int)(x/(w/3));int id=(row*3+col)+(selected/18)*18;if(id>=120)return true;selected=id;if(caught[id])Toast(names[id]+"  •  Lv."+monsterLevel[id]);invalidate();}return true;}
  }
}
